@app.api_route("/v1/previews/{preview_id}/web", methods=["GET", "POST", "PUT", "PATCH", "DELETE"])
@app.api_route("/v1/previews/{preview_id}/web/{path:path}", methods=["GET", "POST", "PUT", "PATCH", "DELETE"])
async def preview_web_proxy(preview_id: str, request: Request, path: str = ""):
    """Browser-facing reverse proxy to a running preview's loopback port — lets a preview be opened
    over the api's tailnet route (the preview's 127.0.0.1 port isn't reachable directly). Auth-exempt
    (gated by the unguessable preview id + TTL) — see require_transport_auth_for_v1."""
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    from .services.preview_service import proxy_preview
    body = await request.body()
    status, ctype, data, headers = proxy_preview(
        engine, preview_id, path, request.method, request.url.query,
        body or None, request.headers.get("content-type"), settings.sandbox_token,
        incoming_headers=dict(request.headers),
    )
    return Response(content=data, status_code=status, media_type=ctype, headers=headers)


@app.websocket("/v1/previews/{preview_id}/web/")
@app.websocket("/v1/previews/{preview_id}/web/{path:path}")
async def preview_websocket_proxy(websocket: WebSocket, preview_id: str, path: str = ""):
    """Bidirectional WebSocket proxy for SPA/live-preview development servers."""
    await websocket.accept()
    with begin(engine) as connection:
        row = connection.execute(text(
            "SELECT url,status,mode FROM app_previews WHERE id=:id"
        ), {"id": preview_id}).mappings().first()
    if row is None or row["status"] != "running" or not row["url"]:
        await websocket.close(code=4404, reason="preview not running")
        return
    base = str(row["url"]).rstrip("/")
    target = ("wss://" + base[8:] if base.startswith("https://") else
              "ws://" + base[7:] if base.startswith("http://") else base)
    target += "/" + path.lstrip("/")
    if websocket.url.query:
        target += "?" + websocket.url.query
    headers = ({"X-Sandbox-Token": settings.sandbox_token}
               if row["mode"] == "rootfs" and settings.sandbox_token else None)
    try:
        import websockets
        async with websockets.connect(target, additional_headers=headers) as upstream:
            async def client_to_upstream():
                while True:
                    message = await websocket.receive()
                    if message.get("text") is not None:
                        await upstream.send(message["text"])
                    elif message.get("bytes") is not None:
                        await upstream.send(message["bytes"])
                    else:
                        return

            async def upstream_to_client():
                async for message in upstream:
                    if isinstance(message, bytes):
                        await websocket.send_bytes(message)
                    else:
                        await websocket.send_text(message)

            await asyncio.gather(client_to_upstream(), upstream_to_client())
    except (WebSocketDisconnect, Exception):  # connection closure is reflected to the browser
        try:
            await websocket.close()
        except Exception:
            pass


@app.get("/v1/previews/{preview_id}/gate")
def preview_gate_endpoint(preview_id: str):
    """What will approving this preview actually do?

    The console must be able to say "approve merges PR #123 and deploys `web` to
    hetzner-ci-01" BEFORE the click. An approval whose consequence is discovered afterwards is
    not an approval.
    """
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    from boss_engine.services.preview_approval import describe_gate

    with begin(engine) as connection:
        found = describe_gate(connection, preview_id=preview_id)
        if not found:
            raise HTTPException(status_code=404, detail="no such preview")
        return found


@app.post("/v1/previews/{preview_id}/approve")
def approve_preview_endpoint(preview_id: str, payload: dict):
    """Approve what the preview shows — the single human gate on the path to live.

    This does NOT deploy. It approves the run's existing `review_pull_request` decision, which
    merges, which fires the one delivery trigger that already exists. Adding a second path into
    `deployment_runs` is the "two copies of one decision" defect that produced the
    preview-resolver and test-oracle bugs, so the seam is deliberately an approval and not a
    deploy call.
    """
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    actor = str(payload.get("actor") or "").strip()
    if not actor:
        raise HTTPException(status_code=422, detail="actor is required")
    from boss_engine.services.preview_approval import (
        PreviewGateError, record_preview_approval,
    )

    with begin(engine) as connection:
        try:
            gate = record_preview_approval(
                connection, preview_id=preview_id, actor=actor,
                note=str(payload.get("note") or "").strip() or None)
        except PreviewGateError as exc:
            raise HTTPException(status_code=exc.status, detail=str(exc))

    # Approve the merge decision through the SAME endpoint a human uses. Calling the existing
    # transition keeps role checks, receipts and the merge itself on one path; a private
    # shortcut here would be a second way to merge.
    decision_id = gate["decision_id"]
    card = approve_decision(
        decision_id,
        DecisionActionRequest(actor=actor,
                              note=f"Preview {preview_id} approved by {actor}"
                                   + (f": {gate['note']}" if gate.get("note") else "")),
    )
    return {"preview_id": preview_id, "decision_id": decision_id,
            "approved_by": actor, "decision": card,
            "app_targets": gate.get("app_targets", []),
            "note": "merge decision approved; delivery follows the merge trigger"}


@app.post("/v1/previews/{preview_id}/stop")
def stop_preview_endpoint(preview_id: str, payload: Optional[dict] = None):
    """Tear down a running preview."""
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    p = payload or {}
    actor = str(p.get("actor") or "").strip()
    if not actor:
        raise HTTPException(status_code=422, detail="actor is required")
    with begin(engine) as connection:
        preview_row = connection.execute(
            text("SELECT project_id FROM app_previews WHERE id = :preview_id"),
            {"preview_id": preview_id},
        ).mappings().first()
        if not preview_row:
            raise HTTPException(status_code=404, detail="Preview not found.")
        require_project_actor(
            connection, preview_row["project_id"], actor, "task_create"
        )
    from .services.preview_service import stop_preview
    try:
        return stop_preview(engine, preview_id, settings)
    except ValueError as exc:
        raise HTTPException(status_code=404, detail=str(exc))


def without_internal_bulk(run: dict) -> dict:
    """Strip engine-internal file bodies before a run crosses the API boundary.

    `finalize_ctx.pending_diff` is how the verifier ratchet re-applies a change after a gate
    failure: a list of {path, content} holding the FULL TEXT of every file the agent wrote. The
    engine needs it. A browser never does — and it was being serialized into the console on
    every page load.

    Measured on goldeneye: 11.4 MB of HTML and 18-67 seconds per page, including EIGHT complete
    package-lock.json files at ~139-176 KB each. The console looked broken because it was
    shipping the repair loop's scratch space to the browser.

    Paths and sizes are kept, so a diff view can still say what changed and fetch a body when
    someone actually opens one.
    """
    fctx = run.get("finalize_ctx")
    if not isinstance(fctx, dict) or "pending_diff" not in fctx:
        return run
    pending = fctx.get("pending_diff")
    if not isinstance(pending, list):
        return run
    summarised = [
        {"path": f.get("path"), "bytes": len(f.get("content") or "")}
        if isinstance(f, dict) else f
        for f in pending
    ]
    return {**run, "finalize_ctx": {**fctx, "pending_diff": summarised}}


#: No LIST row needs a string longer than this. Detail views fetch the whole run.
#: Calibrated, not guessed — against the live 200-row response:
#:   2000 -> 2.24 MB   1000 -> 1.79 MB   500 -> 1.47 MB   200 -> 1.19 MB
#: Below 500 the curve flattens (the remainder is many short fields, not a few long ones)
#: while the risk of clipping something an operator wants to read goes up. A list row shows
#: titles and status lines; 240 characters is already generous for both. Lowered from 500 when
#: the list's ceiling was raised to cover every task: the per-string bound never limited how
#: MANY strings a row carries, and a design plan with forty fields was still ~20 KB after it.
LIST_STRING_BUDGET = 240


def trim_for_list(value: Any, _depth: int = 0) -> Any:
    """Shrink a run to what a LIST can possibly render.

    /v1/code-tasks returns 200 rows, each carrying the full row: design plans, written specs,
    security and review narratives, and the ratchet's file snapshots. Measured on goldeneye
    that was 3.75 MB from the endpoint and ~10 MB of HTML in the console, at 18-22s a page.

    Deliberately a RULE, not a list of field names. Stripping `pending_diff` by name shaved
    11.4 MB to 10.0 MB and left `ratchet.files[].content`, `spec.instructions`,
    `state.design.plan` and five more narratives behind it — the same field-at-a-time chase
    that made everything else here take so long. A list row simply has no use for a 2 KB
    string, whatever it is called, so the bound is on SIZE and applies to fields nobody has
    added yet.

    Truncates rather than deletes: a consumer reading a field still gets a string, and the
    marker says why it is short.
    """
    if isinstance(value, str):
        if len(value) <= LIST_STRING_BUDGET:
            return value
        return value[:LIST_STRING_BUDGET] + f"… [{len(value)} chars; open the run for the rest]"
    if isinstance(value, dict):
        return {k: trim_for_list(v, _depth + 1) for k, v in value.items()}
    if isinstance(value, list):
        return [trim_for_list(v, _depth + 1) for v in value]
    return value


def summarise_run_for_list(run: dict) -> dict:
    """A list row: engine scratch removed, then everything bounded by size."""
    slim = without_internal_bulk(run)
    fctx = slim.get("finalize_ctx")
    if isinstance(fctx, dict) and "ratchet" in fctx:
        # The verifier ratchet's own file snapshots — a second copy of the bodies
        # `pending_diff` already held, and the largest single field in the response.
        ratchet = fctx.get("ratchet")
        if isinstance(ratchet, dict) and isinstance(ratchet.get("files"), list):
            slim = {**slim, "finalize_ctx": {**fctx, "ratchet": {
                **ratchet,
                "files": [{"path": f.get("path"), "bytes": len(f.get("content") or "")}
                          if isinstance(f, dict) else f for f in ratchet["files"]],
            }}}
    return trim_for_list(slim)


@app.post("/v1/jobs/{job_id}/cancel")
def cancel_job_endpoint(job_id: str, payload: Optional[dict] = None):
    """Cancel a job that has not started yet.

    There was no way to un-queue work. When a bulk producer filled the queue the only remedy
    was to wait it out. Refuses anything already leased or running: killing work mid-flight
    leaves a half-written branch and an unowned lease.
    """
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    body = payload or {}
    with begin(engine) as c:
        result = jobs.cancel_queued_job(
            c, job_id, reason=str(body.get("reason") or "cancelled by operator"),
            actor=str(body.get("actor") or "operator"),
            force=bool(body.get("force")))
    if not result.get("ok"):
        raise HTTPException(status_code=409, detail=result.get("error") or "cannot cancel")
    return result


@app.post("/v1/code-tasks/{run_id}/origin")
def set_code_task_origin_endpoint(run_id: str, payload: dict):
    """Record where a run came from, so the console can show its Research/Spec history.

    Origin is written at creation and there was no way to repair it afterwards: a build
    restarted by hand loses the PRD that specified it, and the card then reports "Spec: none"
    about work whose spec is sitting right there in a completed panel.
    """
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    kind = str((payload or {}).get("kind") or "").strip()
    if kind not in ("meeting", "discovery"):
        raise HTTPException(status_code=422, detail="kind must be 'meeting' or 'discovery'")
    origin = {"kind": kind}
    for field in ("meeting_run_id", "task_id", "discovery_run_id"):
        if (payload or {}).get(field):
            origin[field] = str(payload[field])
    with begin(engine) as c:
        n = c.execute(text(
            "UPDATE code_task_runs SET finalize_ctx = COALESCE(finalize_ctx,'{}'::jsonb) "
            "|| jsonb_build_object('origin', CAST(:o AS JSONB)), updated_at = now() "
            "WHERE id = :i"), {"o": json.dumps(origin), "i": run_id}).rowcount
    if not n:
        raise HTTPException(status_code=404, detail="code task not found")
    return {"ok": True, "run_id": run_id, "origin": origin}


@app.get("/v1/code-tasks")
def list_code_tasks_endpoint(project_id: Optional[str] = None, limit: int = 50,
                             exclude_internal: bool = False):
    """List code-task runs for a project (newest first) for the Code Tasks view.

    `exclude_internal` drops BOSS's own maintenance runs BEFORE the limit is applied. The
    console filters them out anyway, but filtering after the limit lets a burst of housekeeping
    consume the whole window -- which is exactly how the Factory came to render an empty grid
    under a heading reading "200 code tasks".
    """
    project_id = resolve_list_project_id(project_id)
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    from .services.code_task_service import count_code_task_runs, list_code_task_runs
    with begin(engine) as c:
        items = [summarise_run_for_list(r)
                 for r in list_code_task_runs(c, project_id, limit,
                                              exclude_internal=exclude_internal)]
        # `total` under the SAME filter, so the console can say "200 of 244" instead of
        # implying that 200 is all there is. Without it a full window and a truncated one look
        # identical, and the Factory has been reporting the second as the first.
        total = count_code_task_runs(c, project_id, exclude_internal=exclude_internal)
        return {
            "project_id": project_id,
            "code_tasks": items,
            "total": total,
            "limit": int(limit),
            "truncated": total > len(items),
        }


@app.get("/v1/code-tasks/{run_id}")
def get_code_task_endpoint(run_id: str):
    """Fetch a single code-task run (status, phase, diff summary, tests, PR, decision)."""
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    from .services.code_task_service import load_code_task_run
    with begin(engine) as c:
        run = load_code_task_run(c, run_id)
    if run is None:
        raise HTTPException(status_code=404, detail="code task not found")
    # Same boundary as the list: opening ONE run should not ship a lockfile either.
    return without_internal_bulk(run)


