        step = payload["step"]
        return {"step": step, "tier": dr.resolve_tier(step),
                "engine": dr.resolve_engine(step, frontier_engine=frontier, oss_engine=oss,
                                            default_engine=settings.code_agent_engine,
                                            overrides=payload.get("overrides"))}
