@app.get("/v1/agent/threads/{thread_id}/messages")
def get_agent_thread_messages_endpoint(thread_id: str, project_id: str, actor: str):
    """Full message history for one chat thread (to restore a conversation)."""
    with begin(engine) as connection:
        require_project_actor(connection, project_id, actor, "agent_chat")
        owner = connection.execute(
            text("SELECT project_id, pending_plan_id, pending_plan_summary "
                 "FROM agent_threads WHERE id = :id"),
            {"id": thread_id},
        ).mappings().first()
        if not owner or owner["project_id"] != project_id:
            raise HTTPException(status_code=404, detail="Agent thread not found.")
        # Re-surface a pending plan on reload so the UI can show the Confirm/Revise controls (else a
        # plan proposed in a prior turn is unreachable — you land on "waiting for confirmation" with
        # no button).
        pending = None
        if owner["pending_plan_id"]:
            pending = {"plan_id": owner["pending_plan_id"],
                       **(owner["pending_plan_summary"] or {})}
        # IS A TURN ACTUALLY STILL RUNNING?
        #
        # The console assumed one was. Past its 240s bound it told the operator "Nothing was
        # cancelled … the answer will appear here on its own", then polled for twenty minutes
        # and went quiet. Measured on the live system while the chat said "BOSS is working…":
        # no agent run in flight at all. The turn had died, and every sentence the console
        # showed after that was a promise it had no basis for.
        #
        # There is no thread id on agent_runs, so this answers the honest question — "is BOSS
        # working on anything for this project right now" — rather than a precise one it cannot
        # ask. A false "yes" costs a little more waiting; a false "no" would tell someone their
        # turn is dead while it runs, so the doubt is spent in that direction deliberately.
        working = bool(connection.execute(
            text("SELECT 1 FROM agent_runs WHERE project_id = :p AND status = 'running' "
                 "AND updated_at > now() - interval '30 minutes' LIMIT 1"),
            {"p": project_id},
        ).first())
        return {
            "thread_id": thread_id,
            "messages": orchestration_agent.list_messages(connection, thread_id),
            "pending_confirmation": pending,
            "working": working,
        }


@app.get("/v1/tasks", response_model=TaskListResponse)
def list_tasks(
    project_id: Optional[str] = None, limit: int = 50, offset: int = 0
) -> TaskListResponse:
    project_id = resolve_list_project_id(project_id)
    if limit < 1 or limit > 200:
        raise HTTPException(status_code=400, detail="limit must be between 1 and 200.")
    if offset < 0:
        raise HTTPException(status_code=400, detail="offset must be >= 0.")
    with begin(engine) as connection:
        rows = connection.execute(
            text(
                """
                SELECT t.id, t.project_id, t.title, t.description, t.status, t.priority,
                       t.risk_tier, t.owner_role_id, t.parent_task_id, t.dependency_task_ids,
                       t.due_at, t.data_boundary, t.dedupe_key, t.created_at, t.updated_at,
                       j.status AS latest_job_status,
                       EXISTS(SELECT 1 FROM decisions d WHERE d.task_id = t.id
                              AND d.status IN ('pending', 'delegated')) AS has_open_decision
                FROM tasks t
                LEFT JOIN LATERAL (
                    SELECT status FROM jobs WHERE task_id = t.id
                    ORDER BY created_at DESC LIMIT 1
                ) j ON TRUE
                WHERE t.project_id = :project_id AND t.status <> 'archived'
                ORDER BY t.created_at DESC
                LIMIT :limit OFFSET :offset
                """
            ),
            {
                "project_id": project_id,
                "limit": limit,
                "offset": offset,
            },
        ).mappings().all()
        return TaskListResponse(
            project_id=project_id,
            items=[task_summary_from_row(row) for row in rows],
            limit=limit,
            offset=offset,
        )


@app.delete("/v1/tasks/{task_id}")
def archive_task_endpoint(task_id: str, project_id: str, actor: str):
    """Archive a task (soft delete) — hide it from lists/rails without breaking child rows (plans,
    code tasks reference it). Used to clear junk/mis-created tasks.

    Requires a project actor with task_create (same gate as create) so knowing a task id alone
    cannot soft-delete another project's work when API auth is off or loosely bound.
    """
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    with begin(engine) as connection:
        require_project_actor(connection, project_id, actor, "task_create")
        row = connection.execute(
            text("UPDATE tasks SET status='archived', updated_at=now() "
                 "WHERE id = :id AND project_id = :p RETURNING id"),
            {"id": task_id, "p": project_id},
        ).first()
        if row is None:
            raise HTTPException(status_code=404, detail="task not found in project")
        # Also close any agent chat thread bound to this task so it drops from the workspace rail.
        connection.execute(
            text("UPDATE agent_threads SET status='closed' "
                 "WHERE project_id = :p AND external_ref = :ref"),
            {"p": project_id, "ref": task_id},
        )
        emit_event(
            connection,
            project_id,
            "task.archived",
            actor,
            "task",
            task_id,
            {"status": "archived"},
        )
    return {"status": "archived", "task_id": task_id}


@app.post("/v1/tasks", response_model=TaskSummary, status_code=201)
def create_task(payload: TaskCreateRequest) -> TaskSummary:
    with begin(engine) as connection:
        require_project_actor(
            connection,
            payload.project_id,
            payload.actor,
            "task_create",
        )
        try:
            result = intake.create_task(
                connection,
                project_id=payload.project_id,
                title=payload.title,
                description=payload.description,
                dedupe_key=payload.dedupe_key,
                priority=payload.priority,
                risk_tier=payload.risk_tier,
                data_boundary=payload.data_boundary,
                inputs=payload.inputs,
                required_artifacts=payload.required_artifacts,
                owner_role_id=payload.owner_role_id,
                parent_task_id=payload.parent_task_id,
                dependency_task_ids=payload.dependency_task_ids,
                due_at=payload.due_at,
            )
        except ValueError as error:
            # Duplicate dedupe_key is a client conflict; other validation stays 400.
            detail = str(error)
            status = (
                409
                if "dedupe_key already exists" in detail
                else 400
            )
            raise HTTPException(status_code=status, detail=detail) from error
        row = connection.execute(
            text(
                """
                SELECT id, project_id, title, description, status, priority, risk_tier,
                       owner_role_id, parent_task_id, dependency_task_ids, due_at,
                       data_boundary, dedupe_key, created_at, updated_at
                FROM tasks
                WHERE id = :task_id
                """
            ),
            {"task_id": result["task_id"]},
        ).mappings().one()
        return task_summary_from_row(row)


