def raise_workflow_error(error: workflow_runtime.WorkflowError) -> None:
    if isinstance(error, workflow_runtime.WorkflowNotFoundError):
        status_code = 404
    elif isinstance(
        error,
        (
            workflow_runtime.WorkflowConflictError,
            workflow_runtime.WorkflowLeaseError,
            workflow_runtime.WorkflowMappingAmbiguousError,
            workflow_runtime.WorkflowBindingBlockedError,
        ),
    ):
        status_code = 409
    else:
        status_code = 422
    raise HTTPException(status_code=status_code, detail=str(error)) from error


# ── Customer delivery workflows ───────────────────────────────────────────────
#
# Everything under /v1/delivery-workflows is namespace-scoped to 'product'. The endpoints
# below cannot see, edit, version or run BOSS's own thirty-three definitions — that is the
# whole point of the separation, and `require_namespace` is what enforces it rather than
# convention.


@app.get("/v1/delivery-workflows/capabilities")
def list_delivery_capabilities(project_id: str | None = None) -> dict:
    """What a step can be. Feeds the builder palette and documents the risk floor."""
    from boss_engine.services.workflow_capabilities import (
        MANUAL_APPROVAL_RISK_FLOOR,
        blocks,
        palette,
    )
    from boss_engine.services import workflow_custom_steps as custom_steps

    # The project's own steps belong in the same palette as the built-in ones — a customer
    # should not have to know which of their steps BOSS wrote. Optional, because the palette is
    # also browsed before a project is chosen.
    custom: list[dict] = []
    if project_id and database_is_reachable(engine):
        with begin(engine) as connection:
            custom = [s for s in custom_steps.list_steps(connection, project_id)
                      if s["enabled"]]

    return {
        "capabilities": palette(),
        "custom_steps": custom,
        # Control blocks the runtime has always supported and the builder never offered, so a
        # customer could only ever author a straight line.
        "blocks": blocks(),
        "manual_approval_risk_floor": MANUAL_APPROVAL_RISK_FLOOR,
        "note": (
            "A capability at or above the risk floor always requires a person, whatever a "
            "workflow asks for."
        ),
    }


@app.get("/v1/delivery-workflows/custom-steps")
def list_delivery_custom_steps(project_id: str) -> dict:
    """A project's own steps, plus everything it could bind a new one to.

    The bindable lists come back with the SAME risk tiers the floor will use, so the builder
    can say "this will need an approval" while the customer is choosing — rather than after
    they try to publish.
    """
    from boss_engine.services.workflow_capabilities import MANUAL_APPROVAL_RISK_FLOOR
    from boss_engine.services import workflow_custom_steps as custom_steps

    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")

    with begin(engine) as connection:
        steps = custom_steps.list_steps(connection, project_id)
        skills = connection.execute(
            text("SELECT skill_id, config, provenance FROM project_skills "
                 "WHERE project_id=:p AND enabled ORDER BY skill_id"),
            {"p": project_id},
        ).mappings().all()
        servers = connection.execute(
            text("SELECT id, name, url, risk_tier, provenance, tool_risk_overrides "
                 "FROM mcp_servers WHERE project_id=:p AND enabled ORDER BY name"),
            {"p": project_id},
        ).mappings().all()

    bindable_skills = []
    for row in skills:
        config = row["config"] if isinstance(row["config"], dict) else {}
        provenance = row["provenance"] if isinstance(row["provenance"], dict) else {}
        declared = config.get("risk_tier")
        bindable_skills.append({
            "skill_id": row["skill_id"],
            "risk_tier": int(declared) if declared is not None
                         else custom_steps.UNKNOWN_RISK,
            "trusted": bool(provenance.get("trusted", False)),
            # Said here rather than left for the customer to infer from a number.
            "unclassified": declared is None,
        })

    mcp = MCPClient(get_settings(), timeout=6.0)
    bindable_servers = []
    for row in servers:
        overrides = (row["tool_risk_overrides"]
                     if isinstance(row["tool_risk_overrides"], dict) else {})
        provenance = row["provenance"] if isinstance(row["provenance"], dict) else {}
        entry = {
            "id": row["id"], "name": row["name"],
            "risk_tier": int(row["risk_tier"] if row["risk_tier"] is not None
                             else custom_steps.UNKNOWN_RISK),
            "trusted": bool(provenance.get("trusted", False)),
            "tools": [], "reachable": True,
        }
        try:
            for tool in (mcp.list_tools(row["url"]) or []):
                name = tool.get("name")
                entry["tools"].append({
                    "name": name,
                    "description": tool.get("description", ""),
                    "risk_tier": int(overrides[name]) if name in overrides
                                 else entry["risk_tier"],
                })
        except Exception as error:
            # An unreachable server is shown, not hidden. Hiding it would look like the server
            # was never registered, and the customer would add it again.
            entry["reachable"] = False
            entry["error"] = f"{type(error).__name__}: {error}"
        bindable_servers.append(entry)

    return {
        "steps": steps,
        "bindable": {"skills": bindable_skills, "mcp_servers": bindable_servers},
        "manual_approval_risk_floor": MANUAL_APPROVAL_RISK_FLOOR,
    }


@app.post("/v1/delivery-workflows/custom-steps")
def create_delivery_custom_step(payload: dict) -> dict:
    """Define a step. The risk tier is NOT accepted from the caller — it is resolved from
    whatever the step binds, which is what stops "custom step" being a way around the floor."""
    from boss_engine.services import workflow_custom_steps as custom_steps

    project_id = str(payload.get("project_id") or "").strip()
    if not project_id:
        raise HTTPException(status_code=400, detail="project_id is required")
    try:
        with begin(engine) as connection:
            return custom_steps.create(
                connection,
                project_id=project_id,
                label=str(payload.get("label") or ""),
                summary=str(payload.get("summary") or ""),
                binding_kind=str(payload.get("binding_kind") or ""),
                skill_id=payload.get("skill_id") or None,
                mcp_server_id=payload.get("mcp_server_id") or None,
                mcp_tool_name=payload.get("mcp_tool_name") or None,
                inputs=payload.get("inputs"),
                knowledge=str(payload.get("knowledge") or ""),
                produces=payload.get("produces"),
                step_key=payload.get("step_key") or None,
                actor=str(payload.get("actor") or "operator"),
            )
    except custom_steps.CustomStepError as error:
        raise HTTPException(status_code=400, detail=str(error)) from error


@app.delete("/v1/delivery-workflows/custom-steps/{step_key}")
def delete_delivery_custom_step(step_key: str, project_id: str, actor: str = "operator") -> dict:
    from boss_engine.services import workflow_custom_steps as custom_steps

    with begin(engine) as connection:
        removed = custom_steps.delete(connection, project_id, step_key, actor)
    if not removed:
        raise HTTPException(status_code=404, detail=f"no custom step '{step_key}'")
    return {"deleted": step_key}


@app.get("/v1/delivery-workflows/catalogue")
def list_delivery_catalogue() -> dict:
    """The workflows BOSS ships, with what each will need from a project.

    Returned from the catalogue module rather than the database so it can be browsed before
    anything has been installed — choosing a workflow should not require having one.
    """
    from boss_engine.services.workflow_catalogue import WORK_CLASSES, catalogue_summary

    return {"items": catalogue_summary(), "work_classes": list(WORK_CLASSES)}


@app.post("/v1/delivery-workflows/catalogue/install")
def install_delivery_catalogue(payload: dict) -> dict:
    """Install the catalogue into a project. Idempotent — safe to call on every boot."""
    from boss_engine.services.workflow_catalogue import seed

    project_id = str(payload.get("project_id") or "").strip()
    if not project_id:
        raise HTTPException(status_code=400, detail="project_id is required")
    with begin(engine) as connection:
        return seed(connection, project_id, actor=str(payload.get("actor") or "boss"))


@app.post("/v1/delivery-workflows/apply")
def apply_delivery_workflow(payload: dict) -> dict:
    """Point a class of work at a workflow.

    "New projects here use Standard Product Delivery." Uses the runtime's existing mapping
    resolution — selector, scope and priority — so an org default and a project override
    behave the way they already do everywhere else.

    IT SETS, IT DOES NOT APPEND. This called `create_mapping` unconditionally, and there is a
    unique index on (project_id, selector_kind, selector_value, scope_type, scope_id, priority)
    WHERE enabled — so the FIRST apply worked and every one after it hit the index and came
    back as:

        HTTP 500  {"detail": "WorkflowConflictError: An enabled mapping already occupies this
                              selector, scope, and priority."}

    which is what the Command Center's workflow picker rendered as `failed (500)`. Not specific
    to Research-Led Discovery — every option failed, including re-picking the one already in
    force, because a mapping for `project.new` was already there. A control whose whole purpose
    is "change which workflow new projects follow" could not change it once.

    The selector is single-valued by construction: that unique index says so. So an apply over
    an occupied slot is a REPLACEMENT, not a collision — it repoints the existing mapping at
    the new version. Anything else asks the operator to go and delete a row they have never
    been shown.
    """
    from boss_engine.services.workflow_catalogue import WORK_CLASSES, work_class_label

    project_id = str(payload.get("project_id") or "").strip()
    workflow_key = str(payload.get("workflow_key") or "").strip()
    work_class = str(payload.get("work_class") or "").strip()
    actor = str(payload.get("actor") or "operator").strip()
    if not project_id or not workflow_key or not work_class:
        raise HTTPException(
            status_code=400,
            detail="project_id, workflow_key and work_class are required",
        )
    if work_class not in WORK_CLASSES:
        raise HTTPException(
            status_code=422,
            detail=f"work_class must be one of: {', '.join(WORK_CLASSES)}",
        )
    with begin(engine) as connection:
        row = connection.execute(
            text(
                # `name` too: the confirmation this returns is read by a person standing in
                # front of a dropdown that shows names, not keys.
                "SELECT id, name, active_version_id FROM workflow_definitions "
                "WHERE project_id=:p AND workflow_key=:k "
                "AND COALESCE(namespace,'system')='product'"
            ),
            {"p": project_id, "k": workflow_key},
        ).mappings().first()
        if row is None:
            raise HTTPException(
                status_code=404,
                detail=f"no delivery workflow '{workflow_key}' in this project",
            )
        version_id = row["active_version_id"]
        if not version_id:
            latest = connection.execute(
                text(
                    "SELECT id FROM workflow_versions WHERE workflow_definition_id=:d "
                    "AND status='published' ORDER BY version DESC LIMIT 1"
                ),
                {"d": row["id"]},
            ).scalar()
            version_id = latest
        if not version_id:
            raise HTTPException(
                status_code=409,
                detail=f"'{workflow_key}' has no published version to apply",
            )
        priority = int(payload.get("priority") or 100)
        # The slot this apply owns — exactly the columns the unique index covers.
        occupant = connection.execute(
            text(
                "SELECT id, workflow_version_id FROM workflow_mappings "
                "WHERE project_id=:p AND selector_kind='work_class' AND selector_value=:sv "
                "AND scope_type='project' AND scope_id=:p AND priority=:pr AND enabled = true"
            ),
            {"p": project_id, "sv": work_class, "pr": priority},
        ).mappings().first()

        if occupant is None:
            mapping = workflow_runtime.create_mapping(
                connection,
                project_id=project_id,
                workflow_version_id=version_id,
                selector_kind="work_class",
                selector_value=work_class,
                scope_type="project",
                scope_id=project_id,
                priority=priority,
                actor=actor,
            )
            outcome = "created"
        elif occupant["workflow_version_id"] == version_id:
            # Re-picking what is already in force. Idempotent, and NOT an error — the picker
            # fires on every change event, including one that lands back where it started.
            mapping = dict(occupant)
            outcome = "unchanged"
        else:
            connection.execute(
                text(
                    "UPDATE workflow_mappings SET workflow_version_id=:v, updated_at=now() "
                    "WHERE id=:i"
                ),
                {"v": version_id, "i": occupant["id"]},
            )
            mapping = connection.execute(
                text("SELECT * FROM workflow_mappings WHERE id=:i"), {"i": occupant["id"]},
            ).mappings().first()
            mapping = dict(mapping) if mapping else {"id": occupant["id"]}
            emit_event(
                connection, project_id, "workflow.mapping_repointed", actor,
                "workflow_mapping", occupant["id"],
                {"selector_value": work_class, "workflow_key": workflow_key,
                 "from_version_id": occupant["workflow_version_id"], "to_version_id": version_id},
            )
            outcome = "replaced"

        # WHAT ACTUALLY RESOLVES NOW, which is not always what was just applied: an org-scoped
        # mapping or one at a higher priority can still win. Reporting "saved" without checking
        # would tell the operator their choice is in force when the runtime disagrees, and the
        # only place that would surface is the next project starting on the wrong workflow.
        in_force = ""
        in_force_name = ""
        try:
            resolved = workflow_runtime.resolve_mapping(
                connection, project_id=project_id,
                selector_kind="work_class", selector_value=work_class,
            )
            selected = (resolved or {}).get("selected") or {}
            in_force = str(selected.get("workflow_key") or "")
            in_force_name = str(selected.get("workflow_name") or "")
        except Exception:  # noqa: BLE001
            # Ambiguous or otherwise unresolvable. The write above succeeded and must stand;
            # what this branch loses is the confirmation, not the change.
            pass

        # IN THE WORDS ON THE SCREEN, not the ones in the index. This said "New project.new work
        # now uses 'research_led_discovery'." beside a dropdown reading "Research-Led Discovery"
        # — a selector value and a workflow key, to confirm a choice the operator had just made
        # in plain English. Both identifiers have display names; both were one column away.
        applied_name = str(row["name"] or workflow_key)
        for_whom = work_class_label(work_class)
        return {
            "applied": mapping, "workflow_key": workflow_key, "work_class": work_class,
            "outcome": outcome,
            "in_force": in_force or workflow_key,
            "in_force_name": in_force_name or applied_name,
            "note": (
                f"Saved — {for_whom} now use {applied_name}."
                if not in_force or in_force == workflow_key else
                f"Saved, but {in_force_name or in_force} still wins for {for_whom}: another "
                "rule outranks this one by scope or priority."
            ),
        }


@app.get("/v1/delivery-workflows/runs")
def list_delivery_runs(project_id: str, limit: int = 25) -> dict:
    """Live and recent delivery runs, each with where it has got to.

    One query for the list and one for the steps, rather than a call per run: a project with
    twenty workflows in flight should cost two round trips to render, not twenty-one.
    """
    with begin(engine) as connection:
        runs = connection.execute(
            text(
                """
                SELECT r.id, r.status, r.actor, r.input, r.blocked_reason, r.error,
                       r.created_at, r.updated_at, r.completed_at,
                       d.workflow_key, d.name AS workflow_name, v.version, v.spec
                FROM workflow_runs r
                JOIN workflow_definitions d ON d.id = r.workflow_definition_id
                JOIN workflow_versions v ON v.id = r.workflow_version_id
                WHERE r.project_id = :project_id
                  AND COALESCE(d.namespace, 'system') = 'product'
                ORDER BY r.updated_at DESC
                LIMIT :limit
                """
            ),
            {"project_id": project_id, "limit": max(1, min(100, limit))},
        ).mappings().all()
        if not runs:
            return {"project_id": project_id, "runs": []}

        ids = [r["id"] for r in runs]
        steps = connection.execute(
            text(
                """
                SELECT s.workflow_run_id, s.step_id, s.step_kind, s.status, s.output,
                       s.evidence, s.last_error, s.decision_id, s.binding_snapshot,
                       s.started_at, s.completed_at, s.attempt,
                       -- WHETHER THE GATE HAS BEEN ANSWERED, which the step's own status does
                       -- not say. A step stays `waiting` until a worker picks the answer up —
                       -- 50 seconds on a good run — and the console read only the step, so an
                       -- approved gate carried on offering "Review and decide" as though the
                       -- click had not happened. Worse for a decision that EXPIRED: the step
                       -- waits forever and the button leads to a dead gate.
                       d.status AS decision_status, d.approved_at AS decision_approved_at
                FROM workflow_step_runs s
                LEFT JOIN decisions d ON d.id = s.decision_id
                WHERE s.workflow_run_id = ANY(:ids)
                ORDER BY s.created_at, s.iteration
                """
            ),
            {"ids": ids},
        ).mappings().all()
        # Computed HERE, while the connection is open — the loop that builds the payload runs
        # after this block has closed it.
        from boss_engine.services.workflow_recheck import blocker_status as _blocker_status

        _blockers = {}
        for _s in steps:
            try:
                _blockers[(_s["workflow_run_id"], _s["step_id"])] = _blocker_status(
                    connection, project_id, dict(_s))
            except Exception:  # noqa: BLE001 — a re-check must never fail the page
                _blockers[(_s["workflow_run_id"], _s["step_id"])] = None

    # THE ORDER THE STEPS RUN IN, NOT THE ORDER THEY WERE INSERTED.
    #
    # Step rows are created as the run advances and as branches are expanded, so `created_at`
    # put a step that has not started yet above one that finished ten minutes ago — in a view
    # whose entire subject is sequence. The version's spec is the authority on order, and the
    # run already carries the exact version it started on.
    spec_order: dict[str, dict[str, int]] = {}
    # WHAT A STEP DOES, FROM THE SPEC THAT DEFINES IT.
    #
    # `capability` was read out of the step's OUTPUT, and a capability handler has no reason to
    # echo its own name into its result — so nearly every step reached the console as
    # `capability: null`. Two operator-visible failures came from that one miss: the deploy
    # step showed no host picker (the picker keys off the capability), and the preview step
    # never received its live preview (attached by matching capability == "preview"), so it
    # said "Nothing is serving this build right now" while the preview was up and serving.
    # The spec is the authority — `steps[].binding.capability` — and the run records the exact
    # version it started on. Output stays a fallback and never overrides the spec.
    spec_capability: dict[str, dict[str, str]] = {}
    for run in runs:
        spec = run["spec"] if isinstance(run["spec"], dict) else {}
        spec_order[run["id"]] = {
            str(step.get("id")): index
            for index, step in enumerate(spec.get("steps") or [])
        }
        capabilities: dict[str, str] = {}
        for step in spec.get("steps") or []:
            binding = step.get("binding") if isinstance(step.get("binding"), dict) else {}
            name = binding.get("capability") or step.get("capability") or step.get("uses")
            if isinstance(name, str) and name:
                capabilities[str(step.get("id"))] = name
        spec_capability[run["id"]] = capabilities

    by_run: dict[str, list] = {r: [] for r in ids}
    for step in steps:
        snapshot = step["binding_snapshot"] or {}
        by_run[step["workflow_run_id"]].append({
            "step_id": step["step_id"],
            "kind": step["step_kind"],
            "status": step["status"],
            "capability": (
                spec_capability.get(step["workflow_run_id"], {}).get(step["step_id"])
                or (snapshot.get("binding") or {}).get("capability")
                or (step["output"] or {}).get("capability")
            ),
            "output": step["output"] or {},
            "evidence": step["evidence"] or [],
            "error": step["last_error"],
            "decision_id": step["decision_id"],
            # WHETHER THE FAILURE ABOVE IS STILL TRUE.
            #
            # A failed step's error is a record of a past attempt, and this view rendered it as
            # a statement about the present — so after the missing deployment target was
            # created, the Deploy step went on saying in red that the app had nowhere to ship
            # to. Re-checked on read, because that is the moment the operator is deciding
            # whether pressing retry is worth anything.
            "blocker": _blockers.get((step["workflow_run_id"], step["step_id"])),
            "decision_status": step["decision_status"],
            "decision_approved_at": (step["decision_approved_at"].isoformat()
                                     if step["decision_approved_at"] else None),
            # What an operator asks about a waiting step: who, and by when.
            "approval": snapshot.get("approval") or {},
            "due_at": snapshot.get("due_at"),
            "timeout_applied": snapshot.get("timeout_applied"),
            "attempt": step["attempt"],
            "started_at": step["started_at"].isoformat() if step["started_at"] else None,
            "completed_at": step["completed_at"].isoformat() if step["completed_at"] else None,
        })

    # A PREVIEW LINK THAT STILL WORKS.
    #
    # The preview step records the preview that was live WHEN IT RAN, and previews expire and
    # are replaced. So the workflow offered a dead URL — "preview not running (status=expired)"
    # — while the project page, which looks the preview up fresh, opened the live one. A link
    # that 404s is worse than no link: it says the thing is broken when it is running.
    live_preview: dict[str, dict] = {}
    task_ids = {
        str(((s["output"] or {}).get("await") or {}).get("id")
            or (s["output"] or {}).get("code_task_run_id") or "")
        for s in steps
    }
    task_ids.discard("")
    if task_ids:
        with begin(engine) as connection:
            # SAME APP, NOT JUST SAME BUILD.
            #
            # Restricting this to the step's OWN code-task run was right about the danger —
            # linking to a different app's preview is a serious lie — and wrong about the
            # boundary. An app gets built more than once; previews expire on the old build
            # while the newest build serves a live one. So the workflow said "Nothing is
            # serving this build right now. Starting one takes a few seconds." about an app
            # the operator was looking at IN ANOTHER TAB, running and serving.
            #
            # `finalize_ctx->>'app_id'` is the identity `stable_app_id` writes at creation, and
            # it already hashes the project in, so a sibling can never be another project's
            # app. The run's own preview still wins when it has one; a sibling is the fallback,
            # and the record says which, so the console can be honest about what it opened.
            #
            # The whole record, not just its url. `url` is where the app is listening ON THE
            # HOST — 127.0.0.1:42543 — which is not reachable from a browser anywhere else.
            # The console already knows how to turn a preview into a link an operator can open
            # (operatorPreviewOpenHref: reject loopback, else the API's /v1/previews/<id>/web/
            # proxy). Handing it the record lets it apply that rule instead of a second one.
            for row in connection.execute(
                text("""
                    WITH wanted AS (
                        SELECT id AS run_id, NULLIF(finalize_ctx->>'app_id', '') AS app_id
                        FROM code_task_runs
                        WHERE id = ANY(:ids)
                    ),
                    candidate AS (
                        SELECT w.run_id, c.id AS build_id
                        FROM wanted w
                        JOIN code_task_runs c
                          ON c.id = w.run_id
                          OR (w.app_id IS NOT NULL
                              AND NULLIF(c.finalize_ctx->>'app_id', '') = w.app_id)
                    )
                    SELECT DISTINCT ON (k.run_id)
                           k.run_id, k.build_id, p.id, p.status, p.url
                    FROM candidate k
                    JOIN app_previews p ON p.run_id = k.build_id
                    WHERE p.status = 'running'
                    ORDER BY k.run_id, (k.build_id = k.run_id) DESC, p.created_at DESC
                """),
                {"ids": list(task_ids)},
            ).mappings():
                live_preview[row["run_id"]] = {
                    "id": row["id"], "status": row["status"], "url": row["url"],
                    "build_id": row["build_id"],
                    # False means: this is a live preview of the same app, from a later build.
                    # The operator should be told that rather than left to assume.
                    "same_build": row["build_id"] == row["run_id"],
                }

    out = []
    for run in runs:
        order = spec_order.get(run["id"], {})
        run_steps = sorted(
            by_run.get(run["id"], []),
            # A step the spec does not mention sorts last rather than first: an unknown step is
            # unusual, and burying the known sequence under it would be the worse failure.
            key=lambda step: order.get(step["step_id"], len(order) + 1),
        )
        # Attach the CURRENT preview to whichever step is about previewing, so the console
        # links to what is running rather than to what once was.
        # THIS RUN'S OWN BUILD, never somebody else's. Falling back to "any running preview"
        # would link an operator to a different app entirely, which is the same failure in a
        # new place.
        own_task = str((run["input"] or {}).get("adopt_code_task_run_id") or "")
        if not own_task:
            for step in run_steps:
                candidate = (step["output"] or {}).get("code_task_run_id") \
                    or ((step["output"] or {}).get("await") or {}).get("id")
                if isinstance(candidate, str) and candidate.startswith("crun_"):
                    own_task = candidate
                    break
        preview = live_preview.get(own_task) if own_task else None
        if preview:
            for step in run_steps:
                # Either fact identifies the preview step. Matching on capability ALONE is what
                # left the link unattached while capability was null; step_id is the operator's
                # own name for it and costs nothing to check.
                if step.get("capability") == "preview" or step.get("step_id") == "preview":
                    step["live_preview"] = preview

        done = sum(1 for s in run_steps if s["status"] in ("succeeded", "skipped"))
        current = next(
            (s for s in run_steps if s["status"] in ("waiting", "running", "leased", "ready")),
            None,
        )
        out.append({
            "id": run["id"],
            "status": run["status"],
            "workflow_key": run["workflow_key"],
            "workflow_name": run["workflow_name"],
            "version": run["version"],
            "actor": run["actor"],
            "input": run["input"] or {},
            "blocked_reason": run["blocked_reason"],
            "error": run["error"],
            "steps": run_steps,
            "step_count": len(run_steps),
            "steps_done": done,
            "current_step": current["step_id"] if current else None,
            # Says what it is waiting FOR, not just that it is waiting.
            "waiting_on": (
                current.get("approval", {}).get("approver_role") or "a decision"
                if current and current["status"] == "waiting" else None
            ),
            "created_at": run["created_at"].isoformat() if run["created_at"] else None,
            "updated_at": run["updated_at"].isoformat() if run["updated_at"] else None,
        })
    return {"project_id": project_id, "runs": out}


@app.get("/v1/delivery-workflows/{workflow_key}/spec")
def get_delivery_workflow_spec(workflow_key: str, project_id: str) -> dict:
    """The steps a workflow currently has, plus what it was forked from.

    The builder opened empty and made a customer rebuild a ten-step workflow from scratch to
    change one thing. `forked_from` is returned alongside so "reset to the standard" has
    something to reset TO.
    """
    with begin(engine) as connection:
        # LEFT JOIN, deliberately. A workflow created from scratch has no published version
        # until it is first saved, and an inner join turned that into a 404 — so the builder
        # would refuse to open the very thing the "New workflow" button had just made.
        row = connection.execute(
            text(
                "SELECT d.id, d.name, d.is_catalogue, d.forked_from_version_id, "
                "       v.id AS version_id, v.version, v.spec "
                "FROM workflow_definitions d "
                "LEFT JOIN workflow_versions v ON v.workflow_definition_id = d.id "
                "WHERE d.project_id=:p AND d.workflow_key=:k "
                "AND COALESCE(d.namespace,'system')='product' "
                "ORDER BY v.version DESC NULLS LAST LIMIT 1"
            ),
            {"p": project_id, "k": workflow_key},
        ).mappings().first()
        if row is None:
            raise HTTPException(status_code=404, detail=f"no workflow '{workflow_key}'")

        origin = None
        if row["forked_from_version_id"]:
            origin_row = connection.execute(
                text("SELECT v.spec, v.version, d.workflow_key, d.name "
                     "FROM workflow_versions v "
                     "JOIN workflow_definitions d ON d.id = v.workflow_definition_id "
                     "WHERE v.id = :id"),
                {"id": row["forked_from_version_id"]},
            ).mappings().first()
            if origin_row:
                origin = {
                    "workflow_key": origin_row["workflow_key"],
                    "name": origin_row["name"],
                    "version": origin_row["version"],
                    "spec": origin_row["spec"],
                }
        return {
            "definition_id": row["id"],
            "workflow_key": workflow_key,
            "name": row["name"],
            "is_catalogue": row["is_catalogue"],
            "version": row["version"],
            # An empty step list rather than null: the builder renders "no steps yet", which is
            # the truth about a brand-new workflow, instead of failing to load.
            "spec": row["spec"] if isinstance(row["spec"], dict) else {"steps": []},
            # What it was forked from, so the builder can offer "reset to the standard" and
            # show what has drifted from it.
            "forked_from": origin,
        }


def _free_workflow_key(connection, project_id: str, name: str) -> str:
    """A key derived from the name, so a customer never has to invent an identifier.

    Shared by create and import. Two callers deriving keys their own way is how one of them
    ends up 409ing on a collision the other would have avoided — which is exactly what the
    first version of forking did.
    """
    base = re.sub(r"[^a-z0-9]+", "_", (name or "").lower()).strip("_") or "workflow"
    taken = {
        row[0] for row in connection.execute(
            text("SELECT workflow_key FROM workflow_definitions WHERE project_id=:p"),
            {"p": project_id},
        )
    }
    key = base
    for suffix in range(2, 500):
        if key not in taken:
            return key
        key = f"{base}_{suffix}"
    return f"{base}_{uuid4().hex[:6]}"


@app.post("/v1/delivery-workflows/create")
def create_delivery_workflow(payload: dict) -> dict:
    """A new workflow, from scratch.

    Creates the definition only. There is no version until the first save, because a workflow
    with no steps is not a thing the runtime can validate — `entry_step` is required — and
    publishing an empty one just to have a row would put an unrunnable version in the ledger.
    """
    project_id = str(payload.get("project_id") or "").strip()
    name = str(payload.get("name") or "").strip()
    actor = str(payload.get("actor") or "operator").strip()
    if not project_id or not name:
        raise HTTPException(status_code=400, detail="project_id and name are required")

    with begin(engine) as connection:
        key = _free_workflow_key(connection, project_id, name)
        definition = workflow_runtime.create_definition(
            connection, project_id=project_id, workflow_key=key, name=name,
            description=str(payload.get("description") or "") or None, actor=actor,
            namespace=workflow_runtime.PRODUCT_NAMESPACE, is_catalogue=False,
        )
    return {"definition": definition}


@app.post("/v1/delivery-workflows/fork")
def fork_delivery_workflow(payload: dict) -> dict:
    """Copy a workflow into one the customer owns and can edit.

    Forking rather than editing in place is what keeps "reset to the standard" meaningful and
    keeps the customer's diff against it visible.
    """
    project_id = str(payload.get("project_id") or "").strip()
    source_key = str(payload.get("workflow_key") or "").strip()
    new_key = str(payload.get("new_key") or "").strip()
    new_name = str(payload.get("new_name") or "").strip()
    actor = str(payload.get("actor") or "operator").strip()
    if not project_id or not source_key:
        raise HTTPException(
            status_code=400, detail="project_id and workflow_key are required"
        )

    with begin(engine) as connection:
        source = connection.execute(
            text(
                "SELECT d.id, d.name, d.description, v.id AS version_id, v.spec "
                "FROM workflow_definitions d "
                "JOIN workflow_versions v ON v.workflow_definition_id = d.id "
                "WHERE d.project_id=:p AND d.workflow_key=:k "
                "AND COALESCE(d.namespace,'system')='product' "
                "ORDER BY v.version DESC LIMIT 1"
            ),
            {"p": project_id, "k": source_key},
        ).mappings().first()
        if source is None:
            raise HTTPException(
                status_code=404, detail=f"no delivery workflow '{source_key}' to fork"
            )
        # Derived when the caller did not name one, so "import this and call it X" cannot
        # collide with something already in the project.
        resolved_key = new_key or _free_workflow_key(
            connection, project_id, new_name or f"{source['name']} copy"
        )
        try:
            definition = workflow_runtime.create_definition(
                connection, project_id=project_id, workflow_key=resolved_key,
                name=new_name or f"{source['name']} (copy)",
                description=source["description"], actor=actor,
                namespace=workflow_runtime.PRODUCT_NAMESPACE,
                is_catalogue=False,
                forked_from_version_id=source["version_id"],
            )
        except workflow_runtime.WorkflowConflictError as error:
            raise HTTPException(status_code=409, detail=str(error)) from error
        try:
            version = workflow_runtime.publish_version(
                connection, project_id=project_id, definition_id=definition["id"],
                spec=source["spec"], actor=actor,
            )
        except workflow_runtime.WorkflowBindingBlockedError as error:
            # Forking a workflow whose custom step has since lost its skill. Named, because
            # "fork failed" would send somebody looking at the fork rather than the binding.
            raise HTTPException(status_code=422, detail=str(error)) from error
        return {"definition": definition, "version": version,
                "forked_from": source["version_id"]}


@app.post("/v1/delivery-workflows/save")
def save_delivery_workflow(payload: dict) -> dict:
    """Publish a new version of a customer's own workflow.

    Saving never mutates a published version — it produces version N+1, so runs in flight keep
    the version they started on and saving cannot change the meaning of work already underway.
    """
    project_id = str(payload.get("project_id") or "").strip()
    definition_id = str(payload.get("definition_id") or "").strip()
    spec = payload.get("spec")
    actor = str(payload.get("actor") or "operator").strip()
    if not project_id or not definition_id or not isinstance(spec, dict):
        raise HTTPException(
            status_code=400, detail="project_id, definition_id and spec are required"
        )
    with begin(engine) as connection:
        try:
            definition = workflow_runtime.require_namespace(
                connection, project_id, definition_id, workflow_runtime.PRODUCT_NAMESPACE
            )
            workflow_runtime.require_editable(definition)
            version = workflow_runtime.publish_version(
                connection, project_id=project_id, definition_id=definition_id,
                spec=spec, actor=actor,
            )
        except workflow_runtime.WorkflowNamespaceError as error:
            raise HTTPException(status_code=403, detail=str(error)) from error
        except workflow_runtime.WorkflowNotFoundError as error:
            raise HTTPException(status_code=404, detail=str(error)) from error
        except workflow_runtime.WorkflowValidationError as error:
            # 422 with the reason: this is what the builder shows next to the step.
            raise HTTPException(status_code=422, detail=str(error)) from error
        except workflow_runtime.WorkflowBindingBlockedError as error:
            # Same treatment, and for the same reason. A custom step's risk tier is resolved
            # from the skill it binds, so "this step always requires a person" is raised here
            # rather than by spec validation — and without this it reached the builder as a
            # bare 500, which tells a customer nothing about what to change.
            raise HTTPException(status_code=422, detail=str(error)) from error
        except workflow_runtime.WorkflowConflictError:
            return {"unchanged": True, "note": "This is identical to the current version."}
        return {"version": version}


@app.delete("/v1/delivery-workflows/{definition_id}")
def delete_delivery_workflow(definition_id: str, project_id: str,
                             actor: str = "operator") -> dict:
    """Remove one of the customer's own workflows.

    Without this the picker only grows: every fork, import and mistake stays forever, and a
    project ends up listing several entries with the same name and no way to tell them apart.
    Refuses catalogue workflows, anything outside the product namespace, and anything with a
    run still going — see `delete_definition` for why each would lose work rather than tidy it.
    """
    if not project_id:
        raise HTTPException(status_code=400, detail="project_id is required")
    with begin(engine) as connection:
        try:
            return workflow_runtime.delete_definition(
                connection, project_id, definition_id, actor)
        except workflow_runtime.WorkflowNamespaceError as error:
            raise HTTPException(status_code=403, detail=str(error)) from error
        except workflow_runtime.WorkflowNotFoundError as error:
            raise HTTPException(status_code=404, detail=str(error)) from error
        except workflow_runtime.WorkflowConflictError as error:
            # 409, with the count: "it has 2 runs still going" is actionable, "cannot delete"
            # is not.
            raise HTTPException(status_code=409, detail=str(error)) from error


@app.post("/v1/delivery-workflows/runs/{run_id}/retry-step")
def retry_delivery_step(run_id: str, payload: dict) -> dict:
    """Put a failed or dead-lettered step back in the queue.

    A step that failed for a reason since dealt with — a target that did not exist, a service
    that was down — had no way back: the run sat dead-lettered and the only recourse was to
    start the whole workflow again and repeat every step before it. This resets THAT step.
    """
    project_id = str(payload.get("project_id") or "").strip()
    step_id = str(payload.get("step_id") or "").strip()
    if not project_id or not step_id:
        raise HTTPException(status_code=400, detail="project_id and step_id are required")
    with begin(engine) as connection:
        row = connection.execute(
            text("SELECT id, status FROM workflow_step_runs "
                 "WHERE workflow_run_id=:r AND project_id=:p AND step_id=:s "
                 "ORDER BY created_at DESC LIMIT 1"),
            {"r": run_id, "p": project_id, "s": step_id},
        ).mappings().first()
        if not row:
            raise HTTPException(status_code=404, detail="step not found on this run")
        if row["status"] not in ("failed", "deadlettered", "cancelled"):
            # Re-queueing a step that is running would run it twice.
            raise HTTPException(
                status_code=409,
                detail=f"'{step_id}' is {row['status']}, so there is nothing to retry.")
        connection.execute(
            text("UPDATE workflow_step_runs SET status='ready', attempt=0, last_error=NULL, "
                 "lease_owner=NULL, lease_expires_at=NULL, updated_at=now() WHERE id=:id"),
            {"id": row["id"]},
        )
        # The RUN has to come back too, or a re-queued step sits ready under a dead run.
        connection.execute(
            text("UPDATE workflow_runs SET status='running', blocked_reason=NULL, error=NULL, "
                 "updated_at=now() WHERE id=:r AND project_id=:p"),
            {"r": run_id, "p": project_id},
        )
    return {"run_id": run_id, "step_id": step_id, "status": "ready"}


@app.post("/v1/delivery-workflows/runs/{run_id}/recheck")
def recheck_delivery_run(run_id: str, payload: dict) -> dict:
    """Re-test what stopped this run, and put back whatever can now proceed.

    The manual refresh an operator asked for after watching BOSS fix the very thing a step was
    still complaining about — and the operation the first fixing investigation reported as
    missing, having had to reconcile a dead-lettered run with hand-written SQL because nothing
    exposed this.
    """
    from boss_engine.services.workflow_recheck import recheck_run

    project_id = str(payload.get("project_id") or "").strip()
    if not project_id:
        raise HTTPException(status_code=400, detail="project_id is required")
    with begin(engine) as connection:
        return recheck_run(connection, project_id=project_id, run_id=run_id,
                           requeue=bool(payload.get("requeue", True)))


@app.post("/v1/delivery-workflows/runs/{run_id}/deploy-target")
def prepare_delivery_deploy_target(run_id: str, payload: dict) -> dict:
    """Give this run somewhere to ship to, and point its deploy step at it.

    `deploy_app` refuses unless an ACTIVE target already exists for the environment, and it
    never creates one — by design, it does not make infrastructure. So the release gate could
    offer only targets belonging to OTHER apps, and a project that had just been built for the
    first time had no way to be deployed at all. Choosing a HOST is the missing act: a target is
    that host plus this app's name, environment and port.

    Idempotent: an app already registered for this environment is reused rather than refused,
    because pressing the button twice should not be an error.
    """
    project_id = str(payload.get("project_id") or "").strip()
    host_id = str(payload.get("host_id") or "").strip()
    environment = str(payload.get("environment") or "staging").strip()
    actor = str(payload.get("actor") or "operator").strip()
    if not project_id or not host_id:
        raise HTTPException(status_code=400, detail="project_id and host_id are required")

    with begin(engine) as connection:
        run = connection.execute(
            text("SELECT input FROM workflow_runs WHERE id=:r AND project_id=:p"),
            {"r": run_id, "p": project_id},
        ).mappings().first()
        if not run:
            raise HTTPException(status_code=404, detail="run not found")
        run_input = run["input"] or {}
        app_name = str(run_input.get("title") or "").strip()
        code_task_run_id = str(run_input.get("adopt_code_task_run_id") or "").strip()
        repo = str(run_input.get("repository") or "").strip()
        if code_task_run_id and not repo:
            repo = connection.execute(
                text("SELECT spec->>'repo' FROM code_task_runs WHERE id=:r"),
                {"r": code_task_run_id},
            ).scalar() or ""
        if not app_name:
            raise HTTPException(status_code=422,
                                detail="this run has no title, so the app has no name")

        host = connection.execute(
            text("SELECT id, name, address, ssh_user, ssh_port, port_min, port_max, status "
                 "FROM deployment_hosts WHERE id=:h AND project_id=:p"),
            {"h": host_id, "p": project_id},
        ).mappings().first()
        if not host:
            raise HTTPException(status_code=404, detail="host not found")
        if host["status"] not in ("verified", "ready", "active"):
            raise HTTPException(
                status_code=409,
                detail=f"host '{host['name']}' is {host['status']} — it has not been verified, "
                       f"so shipping to it would fail at the first connection.")

        existing = connection.execute(
            text("SELECT id, status FROM deployment_targets "
                 "WHERE project_id=:p AND app_name=:a AND environment=:e"),
            {"p": project_id, "a": app_name, "e": environment},
        ).mappings().first()
        if existing:
            if existing["status"] != "active":
                connection.execute(
                    text("UPDATE deployment_targets SET status='active', updated_at=now() "
                         "WHERE id=:i"), {"i": existing["id"]})
            target_id = existing["id"]
            created = False
        else:
            # A PORT NOBODY ELSE IS ON. Existing targets record theirs in `domains` as
            # host:port, so the ones in use are readable without a separate ledger.
            taken = set()
            for row in connection.execute(
                text("SELECT domains FROM deployment_targets WHERE project_id=:p"),
                {"p": project_id},
            ).mappings():
                for domain in (row["domains"] or []):
                    _, _, port = str(domain).rpartition(":")
                    if port.isdigit():
                        taken.add(int(port))
            low = int(host["port_min"] or 3000)
            high = int(host["port_max"] or (low + 200))
            port = next((n for n in range(low, high + 1) if n not in taken), None)
            if port is None:
                raise HTTPException(
                    status_code=409,
                    detail=f"host '{host['name']}' has no free port between {low} and {high}.")
            target_id = make_id("deptgt")
            connection.execute(text("""
                INSERT INTO deployment_targets
                  (id, project_id, app_name, repo, environment, target_kind, target_ref,
                   domains, required_resources, secret_refs, health_checks, status, created_by,
                   created_at, updated_at)
                VALUES (:id,:p,:app,:repo,:env,'ssh',:ref,CAST(:dom AS JSONB),'[]'::jsonb,
                        '[]'::jsonb,CAST(:hc AS JSONB),'active',:by, now(), now())
            """), {
                "id": target_id, "p": project_id, "app": app_name, "repo": repo or "",
                "env": environment,
                "ref": f"{host['ssh_user'] or 'root'}@{host['address']}:{host['ssh_port'] or 22}",
                "dom": json.dumps([f"{host['address']}:{port}"]),
                "hc": json.dumps([{"kind": "http", "path": "/", "expect": 200,
                                   "scheme": "http"}]),
                "by": actor,
            })
            created = True

        # BIND IT TO THE HOST. THIS IS THE WHOLE POINT OF CHOOSING ONE.
        #
        # Neither branch did. The insert set `target_ref` and `domains` and left `host_id`
        # NULL, and the "idempotent" reuse branch returned an existing row completely
        # untouched. Three consequences, all of which an operator reported:
        #
        #   * EVERY DEPLOY WAS BLOCKED. `secret_ref_for` resolves a target's ssh_key through
        #     `host_id` — that is the fleet's "one key per host" promise — so with it NULL the
        #     preflight said "no ssh_key bound to this target and no global ssh key
        #     configured" while the host sat VERIFIED two panels away.
        #   * The host card said "0 apps · Nothing points here yet" forever, because what
        #     points at a host IS host_id.
        #   * Choosing a host in the release gate appeared to do NOTHING, because for an app
        #     whose target already existed — the normal case, since the target is created
        #     when the app is registered — the reuse branch wrote nothing at all.
        #
        # Idempotent still means "pressing twice is not an error". It does not mean "the
        # second press does nothing": re-binding is exactly how an operator MOVES an app to a
        # different host, and refusing that silently is worse than refusing it loudly.
        #
        # `target_ref` and `domains` are re-derived from the host too, so a rebound target
        # cannot keep pointing its address at the machine it used to live on.
        rebind = {"i": target_id, "h": host_id,
                  "ref": f"{host['ssh_user'] or 'root'}@{host['address']}:"
                         f"{host['ssh_port'] or 22}"}
        connection.execute(text(
            "UPDATE deployment_targets SET host_id=:h, target_ref=:ref, updated_at=now() "
            "WHERE id=:i"), rebind)
        # A port on THIS host. Kept if it already names this address, re-issued if the target
        # is moving, so two apps on one host cannot be handed the same port.
        current = connection.execute(
            text("SELECT domains FROM deployment_targets WHERE id=:i"), {"i": target_id},
        ).scalar()
        addr = str(host["address"] or "")
        has_here = any(str(d).startswith(f"{addr}:") for d in (current or []))
        if not has_here:
            taken = set()
            for row in connection.execute(
                text("SELECT id, domains FROM deployment_targets "
                     "WHERE project_id=:p AND host_id=:h"),
                {"p": project_id, "h": host_id},
            ).mappings():
                if row["id"] == target_id:
                    continue
                for domain in (row["domains"] or []):
                    _, _, taken_port = str(domain).rpartition(":")
                    if taken_port.isdigit():
                        taken.add(int(taken_port))
            low = int(host["port_min"] or 3000)
            high = int(host["port_max"] or (low + 200))
            free = next((n for n in range(low, high + 1) if n not in taken), None)
            if free is None:
                raise HTTPException(
                    status_code=409,
                    detail=f"host '{host['name']}' has no free port between {low} and {high}.")
            connection.execute(
                text("UPDATE deployment_targets SET domains=CAST(:d AS JSONB), updated_at=now() "
                     "WHERE id=:i"),
                {"d": json.dumps([f"{addr}:{free}"]), "i": target_id})

        # AND POINT THE RUN AT IT. `deploy` reads target_id and environment as optional inputs,
        # filled from the run's own input — so this is the same mechanism, not a new one.
        connection.execute(
            text("UPDATE workflow_runs SET input = COALESCE(input,'{}'::jsonb) "
                 "|| CAST(:v AS JSONB), updated_at=now() WHERE id=:r AND project_id=:p"),
            {"v": json.dumps({"target_id": target_id, "environment": environment}),
             "r": run_id, "p": project_id},
        )
        target = connection.execute(
            text("SELECT id, app_name, environment, target_ref, domains, host_id "
                 "FROM deployment_targets WHERE id=:i"), {"i": target_id},
        ).mappings().first()
    return {"run_id": run_id, "created": created, "host": host["name"],
            "bound_to_host": host_id, "target": dict(target)}


@app.post("/v1/delivery-workflows/runs/{run_id}/input")
def set_delivery_run_input(run_id: str, payload: dict) -> dict:
    """Set a value the remaining steps will read — the deployment target, most of all.

    `deploy` takes an optional `target_id`, and optional inputs are filled from the run's own
    input. So choosing where to ship, at the moment of approving the release, is a write here
    rather than a new plumbing path.

    Deliberately an allowlist: a run's input is what its steps were bound against, and letting
    a form overwrite any of it would let somebody redirect a build after the fact.
    """
    # `title` is on the list because a run can end up misnamed and there was no way to correct
    # it. Two runs reached the console called "Product Requirements Document (PRD)" — the
    # naming bug behind that is fixed, but the rows already written kept the bad name for good,
    # since the title is stamped at creation.
    #
    # It is not purely cosmetic: `build` reads `title`, so renaming a run that has not built
    # yet also renames the work it starts. That is the desired behaviour for a correction and
    # the reason this is an operator action rather than something the console does silently.
    ALLOWED = {"target_id", "environment", "title"}
    project_id = str(payload.get("project_id") or "").strip()
    values = payload.get("values") if isinstance(payload.get("values"), dict) else {}
    clean = {k: v for k, v in values.items() if k in ALLOWED and isinstance(v, str) and v.strip()}
    if not project_id:
        raise HTTPException(status_code=400, detail="project_id is required")
    if not clean:
        raise HTTPException(
            status_code=400,
            detail=f"nothing to set; allowed: {', '.join(sorted(ALLOWED))}")
    with begin(engine) as connection:
        updated = connection.execute(
            text("UPDATE workflow_runs SET input = COALESCE(input,'{}'::jsonb) "
                 "|| CAST(:v AS JSONB), updated_at=now() "
                 "WHERE id=:r AND project_id=:p RETURNING id"),
            {"v": json.dumps(clean), "r": run_id, "p": project_id},
        ).first()
        if not updated:
            raise HTTPException(status_code=404, detail="run not found")
    return {"run_id": run_id, "set": clean}


@app.post("/v1/delivery-workflows/start")
def start_delivery_workflow(payload: dict) -> dict:
    """Launch a piece of work on a workflow."""
    project_id = str(payload.get("project_id") or "").strip()
    work_class = str(payload.get("work_class") or "").strip()
    workflow_key = str(payload.get("workflow_key") or "").strip()
    actor = str(payload.get("actor") or "operator").strip()
    run_input = payload.get("input") if isinstance(payload.get("input"), dict) else {}
    # ADOPTION IS NOT SOMETHING A CALLER GETS TO ASSERT.
    #
    # `adopt_*` tells the runtime "this work already happened, go and watch it rather than
    # doing it". It is set by start_project_run, from inside, when a code task creates the run
    # that governs it — the one case where the claim is true by construction.
    #
    # Accepting it from a client let "Run this workflow again" hand back the previous run's
    # input whole, so a re-run adopted the same finished build: research recorded as not-run,
    # the old panel and approval adopted, `build` green in seconds against yesterday's code.
    # The console now strips them, but a console is a client — and the next client, or an
    # unrefreshed browser running last week's bundle, would do it again. Refused here, where
    # it cannot be got wrong.
    dropped = sorted(k for k in run_input if k.startswith("adopt_"))
    run_input = {k: v for k, v in run_input.items() if not k.startswith("adopt_")}
    if not project_id or not (work_class or workflow_key):
        raise HTTPException(
            status_code=400,
            detail="project_id and one of work_class or workflow_key are required",
        )

    # "SURPRISE ME" — a real piece of work, chosen for THIS workflow's class.
    #
    # The catalogue's "Start one" sent {"directive": "Describe the work here"}. The panel then
    # convened and debated that phrase, the spec review approved it, and the builder tried to
    # build it: every step ran and none did anything, which demonstrates the workflow by
    # showing it produce nothing.
    #
    # Chosen HERE rather than in the console because the sample has to know the project — a
    # follow-up needs an app that exists, and a product idea must be one this project has not
    # already built (duplicate work is refused at the build, so a repeat would end the demo on
    # an error). A console cannot know either of those.
    if payload.get("sample"):
        from boss_engine.services.workflow_samples import sample_for, why_no_sample

        with begin(engine) as connection:
            wanted = work_class
            if not wanted and workflow_key:
                wanted = connection.execute(
                    text("SELECT work_class FROM workflow_definitions "
                         "WHERE project_id = :p AND workflow_key = :k LIMIT 1"),
                    {"p": project_id, "k": workflow_key},
                ).scalar() or ""
            chosen = sample_for(connection, project_id, str(wanted or ""))
        if not chosen:
            # REFUSING IS THE CORRECT ANSWER when the project cannot supply an example. The
            # alternative is a run against an app that does not exist.
            raise HTTPException(status_code=409, detail=why_no_sample(str(wanted or "")))
        run_input = {**chosen, **run_input}
    with begin(engine) as connection:
        version_id = None
        if workflow_key:
            version_id = connection.execute(
                text(
                    "SELECT v.id FROM workflow_versions v "
                    "JOIN workflow_definitions d ON d.id = v.workflow_definition_id "
                    "WHERE d.project_id=:p AND d.workflow_key=:k "
                    "AND COALESCE(d.namespace,'system')='product' "
                    "ORDER BY v.version DESC LIMIT 1"
                ),
                {"p": project_id, "k": workflow_key},
            ).scalar()
            if not version_id:
                raise HTTPException(
                    status_code=404, detail=f"no delivery workflow '{workflow_key}'"
                )
        try:
            run = workflow_runtime.start_run(
                connection, project_id=project_id, actor=actor, input_data=run_input,
                dedupe_key=str(payload.get("dedupe_key") or "")
                           or f"delivery:{work_class or workflow_key}:{uuid4().hex[:12]}",
                workflow_version_id=version_id,
                selector_kind=None if version_id else "work_class",
                selector_value=None if version_id else work_class,
            )
        except workflow_runtime.WorkflowMappingNotFoundError as error:
            # The honest failure: nobody chose a workflow for this class of work. Picking one
            # anyway is how work silently follows a process nobody agreed to.
            raise HTTPException(status_code=409, detail=str(error)) from error
        except workflow_runtime.WorkflowBindingBlockedError as error:
            raise HTTPException(status_code=422, detail=str(error)) from error
        # Named in the response rather than dropped in silence: a caller that asked for
        # adoption and did not get it should be able to see that, not wonder why its run
        # behaved differently from the one it copied.
        return {"run": run, **({"ignored_input": dropped} if dropped else {})}


